INSERT INTO courses(id,slug,audience,level,topic,title,subtitle,description,outcomes,modules,mentor_id,hours,languages,featured,is_new,bestseller,age_range,certificate,cpd_points,rating,review_count,learners) VALUES ('c-little-project-heroes','little-project-heroes','kids','beginner','projects','{"ar":"أبطال المشاريع الصغار","en":"Little Project Heroes"}'::jsonb,'{"ar":"خطّط مهمتك وأنجزها مع فريقك كأنك قائد حقيقي","en":"Plan your mission and finish it with your team like a real leader"}'::jsonb,'{"ar":"في هذه المغامرة يتعلم الأطفال كيف يحوّلون فكرة إلى خطة: يحددون الهدف، ويوزّعون الأدوار، ويتابعون التقدّم عبر ألعاب وتحديات ممتعة، وينهون الدورة بمشروع صغير يفخرون به.","en":"In this adventure children learn to turn an idea into a plan: set a goal, share roles and track progress through games and challenges, finishing with a small project they are proud of."}'::jsonb,'[{"ar":"يحدد هدفًا واضحًا لمهمته","en":"Sets a clear goal for a mission"},{"ar":"يقسّم العمل إلى خطوات صغيرة","en":"Breaks work into small steps"},{"ar":"يتعاون مع فريقه ويوزّع الأدوار","en":"Works with a team and shares roles"},{"ar":"يعرض مشروعه بثقة","en":"Presents their project with confidence"}]'::jsonb,'[{"id":"m1","title":{"ar":"مرحبًا بالأبطال","en":"Welcome, heroes"},"lessons":[{"id":"l1","title":{"ar":"ما هو المشروع؟","en":"What is a project?"},"minutes":8,"kind":"video","preview":true},{"id":"l2","title":{"ar":"اختر مهمتك","en":"Choose your mission"},"minutes":10,"kind":"video","preview":false}]},{"id":"m2","title":{"ar":"الخطة والفريق","en":"Plan and team"},"lessons":[{"id":"l3","title":{"ar":"خريطة الخطوات","en":"The step map"},"minutes":12,"kind":"video","preview":false},{"id":"l4","title":{"ar":"لعبة الأدوار","en":"The roles game"},"minutes":15,"kind":"live","preview":false},{"id":"l5","title":{"ar":"اختبار سريع","en":"Quick quiz"},"minutes":6,"kind":"quiz","preview":false}]},{"id":"m3","title":{"ar":"العرض الكبير","en":"The big show"},"lessons":[{"id":"l6","title":{"ar":"جهّز عرضك","en":"Prepare your show"},"minutes":14,"kind":"video","preview":false},{"id":"l7","title":{"ar":"حفل الأبطال","en":"Heroes'' showcase"},"minutes":30,"kind":"live","preview":false}]}]'::jsonb,'m3',6,ARRAY['ar']::text[],true,false,true,'6–9',true,NULL,4.9,142,1820);
